'use strict';
/* Visual invoice editor: stores only the existing safe template fields. */
(function(){
  const sectionNames={header:'Business header',details:'Customer & vehicle details',items:'Services & spare parts',totals:'Totals & payment balance',payment:'QR & stamp',bank:'Bank details',footer:'Footer'};
  const escText=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  function base(){return typeof defaultTemplate==='function'?defaultTemplate('regular'):{id:'',name:'My Invoice Template',mode:'regular',accent:'#1d4ed8',logoSize:70,heading:'',footerNote:'',order:Object.keys(sectionNames),hidden:[],layout:{width:210,height:297,margin:10,font:11,spacing:6,enabled:true}}}
  function editor(template){
    let t=structuredClone(template||base());
    const preview=()=>`<div class="aieBrand" style="border-color:${escText(t.accent)}">${escText(db.settings?.name||'BIKE DOCTOR')}<small>${escText(t.heading||'TAX INVOICE')}</small></div>${t.order.filter(k=>!t.hidden.includes(k)).map(k=>`<section data-preview-section="${k}"><h4>${sectionNames[k]}</h4><div class="aieLines"></div></section>`).join('')}<footer>${escText(t.footerNote||'Thank you for your business')}</footer>`;
    const draw=()=>`<div class="advancedInvoiceEditor"><aside><label class="field"><span>Template name</span><input id="aieName" value="${escText(t.name)}"></label><label class="field"><span>Header text</span><input id="aieHeading" value="${escText(t.heading||'')}"></label><label class="field"><span>Footer text</span><textarea id="aieFooter">${escText(t.footerNote||'')}</textarea></label><div class="formgrid"><label class="field"><span>Paper</span><select id="aiePaper"><option value="A4" ${t.layout.width===210?'selected':''}>A4</option><option value="A5" ${t.layout.width===148?'selected':''}>A5</option></select></label><label class="field"><span>Accent</span><input id="aieAccent" type="color" value="${t.accent||'#1d4ed8'}"></label></div><h4>Invoice sections</h4><p>Drag sections to reorder them. Uncheck a section to hide it.</p><div id="aieSections">${t.order.map((key,i)=>`<div class="aieSection" draggable="true" data-section="${key}"><input type="checkbox" data-visible="${key}" ${t.hidden.includes(key)?'':'checked'} ${['header','details','items','totals'].includes(key)?'disabled':''}><span>☰ ${sectionNames[key]||key}</span><button type="button" data-up="${i}" ${i?'':'disabled'}>↑</button><button type="button" data-down="${i===t.order.length-1?'disabled':''}">↓</button></div>`).join('')}</div><label class="customToggle"><input id="aieDefault" type="checkbox" checked> Use as default invoice</label><button id="aieSave" class="btn" type="button">Save visual template</button><p id="aieStatus" role="status"></p></aside><main><div class="aieToolbar"><strong>Live invoice preview</strong><span>Drag sections on the left to rearrange</span></div><div class="aiePreview"><div class="aiePaper">${preview()}</div></div></main></div>`;
    openModal('Advanced Invoice Editor',draw());
    const root=$('.advancedInvoiceEditor'); if(!root)return;
    const sync=()=>{t.name=$('#aieName').value.trim()||'My Invoice Template';t.heading=$('#aieHeading').value;t.footerNote=$('#aieFooter').value;t.accent=$('#aieAccent').value;let p=$('#aiePaper').value;t.layout.width=p==='A5'?148:210;t.layout.height=p==='A5'?210:297;t.hidden=[...root.querySelectorAll('[data-visible]:not(:checked)')].map(x=>x.dataset.visible);const paper=root.querySelector('.aiePaper');paper.style.setProperty('--aie-accent',t.accent);paper.innerHTML=preview()};
    root.querySelectorAll('input,textarea,select').forEach(x=>x.addEventListener('input',sync));
    let dragged=null;root.querySelectorAll('.aieSection').forEach(row=>{row.addEventListener('dragstart',()=>dragged=row);row.addEventListener('dragover',e=>e.preventDefault());row.addEventListener('drop',e=>{e.preventDefault();if(dragged&&dragged!==row){row.parentNode.insertBefore(dragged,row);t.order=[...root.querySelectorAll('.aieSection')].map(x=>x.dataset.section);sync()}})});
    root.querySelectorAll('[data-up],[data-down]').forEach(b=>b.onclick=()=>{let row=b.closest('.aieSection'),target=b.hasAttribute('data-up')?row.previousElementSibling:row.nextElementSibling;if(target){row.parentNode.insertBefore(b.hasAttribute('data-up')?row:target,b.hasAttribute('data-up')?target:row);t.order=[...root.querySelectorAll('.aieSection')].map(x=>x.dataset.section);editor(t)}});
    $('#aiePaper').onchange=sync;
    $('#aieSave').onclick=()=>{try{let saved=saveInvoiceTemplate(t,$('#aieDefault').checked);if(saved)$('#aieStatus').textContent='Saved. The template is available in your invoice designs.'}catch(e){$('#aieStatus').textContent=e.message}};
    sync();
  }
  const before=settingsPage;
  settingsPage=function(){const presets=(db.invoiceTemplates||[]).filter(t=>t.mode==='regular'&&String(t.id).indexOf('TPL-PRESET-')===0);const options=presets.map(t=>`<option value="${escText(t.id)}">${escText(t.name)}</option>`).join('');return before()+`<section class="panel advancedInvoiceEditorLaunch"><div class="panelhead"><h2>Advanced Invoice Editor</h2></div><div class="panelbody"><p>Edit your invoice visually with drag-and-drop sections and a live preview.</p><div class="aieLaunchRow"><select id="advancedInvoicePreset" aria-label="Choose a pre-designed invoice template"><option value="">Choose a pre-designed template</option>${options}</select><button type="button" class="btn" id="openAdvancedInvoiceEditor">Open Advanced Editor</button></div></div></section>`};
  const oldRender=render;
  render=function(){oldRender();if(page!=='settings')return;$('#openAdvancedInvoiceEditor')?.addEventListener('click',()=>{const id=$('#advancedInvoicePreset')?.value;const chosen=id?(db.invoiceTemplates||[]).find(t=>t.id===id):null;editor(chosen||base())})};
  render();
})();
